MOTIF_NAME = 'bishop_attacking_king_zone'
MOTIF_DESCRIPTION = 'The side to move has a bishop attacking squares adjacent to the opponent king while the opponent has no such bishop attack on the side-to-move king.'
def motif(fen: str) -> bool:
    import chess
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm

    opp_king_sq = board.king(opp)
    if opp_king_sq is None:
        return False
    stm_king_sq = board.king(stm)
    if stm_king_sq is None:
        return False

    king_zone = []
    kf = chess.square_file(opp_king_sq)
    kr = chess.square_rank(opp_king_sq)
    for df in (-1, 0, 1):
        for dr in (-1, 0, 1):
            if df == 0 and dr == 0:
                continue
            nf = kf + df
            nr = kr + dr
            if 0 <= nf <= 7 and 0 <= nr <= 7:
                king_zone.append(chess.square(nf, nr))

    stm_bishops = board.pieces(chess.BISHOP, stm)
    stm_attacks_zone = False
    for bsq in stm_bishops:
        attacks = board.attacks(bsq)
        for zsq in king_zone:
            if zsq in attacks:
                stm_attacks_zone = True
                break
        if stm_attacks_zone:
            break

    if not stm_attacks_zone:
        return False

    stm_king_zone = []
    kf2 = chess.square_file(stm_king_sq)
    kr2 = chess.square_rank(stm_king_sq)
    for df in (-1, 0, 1):
        for dr in (-1, 0, 1):
            if df == 0 and dr == 0:
                continue
            nf = kf2 + df
            nr = kr2 + dr
            if 0 <= nf <= 7 and 0 <= nr <= 7:
                stm_king_zone.append(chess.square(nf, nr))

    opp_bishops = board.pieces(chess.BISHOP, opp)
    opp_attacks_zone = False
    for bsq in opp_bishops:
        attacks = board.attacks(bsq)
        for zsq in stm_king_zone:
            if zsq in attacks:
                opp_attacks_zone = True
                break
        if opp_attacks_zone:
            break

    return not opp_attacks_zone
